def parse_attr(self, attr):
    def tilde_unescape(string):
        def repl(m):
            if m.group(1) == '1':
                return '/'
            elif m.group(1) == 'a':
                return ','
            elif m.group(1) == 'b':
                return '@'

        s1 = self.tildeEscape_re.sub(repl, string)
        return re.sub('~0', '~', s1)

    attrs = attr.split('/')
    attrs = [tilde_unescape(a) for a in attrs]
    attrs = [a for a in attrs if a != '@key']
    return attrs

