def method(self, handle, methodName, args, subtypes, addr, userId):
    """
    Handle incoming method calls.
    """
    self.log.debug("Method called: name = %s \n args = %s \n handle = %s \n addr = %s \n subtypes = %s \n userId = %s", methodName, args, handle, addr, subtypes, userId)

    try:

        if (addr == self.image_factory_addr):
            target_obj = self.image_factory
        elif (repr(addr) in self.managedObjects):
            target_obj = self.managedObjects[repr(addr)]
        else:
            raise RuntimeError("%s does not match an object managed by ImageFactoryAgent!  Unable to respond to %s." % (repr(addr), methodName))

        result = getattr(target_obj, methodName)(**args)

        if ((addr == self.image_factory_addr) and (methodName in ("image", "provider_image"))):
            build_adaptor_instance_name = "build_adaptor:%s:%s" %  (methodName, result.builder.image_id)
            qmf_object_addr = self.session.addData(result.qmf_object, build_adaptor_instance_name, persistent=True)
            result.agent = qmf_object.getAgent()
            self.managedObjects[repr(qmf_object_addr)] = result
            handle.addReturnArgument("build_adaptor", qmf_object_addr.asMap())
            self.session.methodSuccess(handle)
        elif(result and isinstance(result, dict)):
            for key in result:
                handle.addReturnArgument(key, result[key])
            self.session.methodSuccess(handle)
        else:
            returned_dictionary = {}
            for method in type(target_obj).qmf_schema.getMethods():
                if (method.getName() == methodName):
                    for method_arg in method.getArguments():
                        if (method_arg.getDirection() == DIR_OUT):
                            returned_dictionary.update({method_arg.getName() : method_arg.getDesc()})
            raise RuntimeError("Method '%s' on objects of class %s must return a dictionary of %s" % (methodName, target_obj.__class__.__name__, returned_dictionary))
    except Exception as e:
        self.log.exception(str(e))
        self.session.raiseException(handle, str(e))

def register_length(self) -> int | None:
    """The size of the operator that can be generated from this ``PolynomialTensor``."""
    for key in self._data:
        if key == "":
            continue
        return self[key].shape[0]
    return None

def execute(self, *args):
    valid = EssentialParameters(
        self.__class__.__name__,
        [self._src_dir, self._src_pattern, self._format],
    )
    valid()

    files = super().get_target_files(self._src_dir, self._src_pattern)
    self.check_file_existence(files)

    dir = self._dest_dir if self._dest_dir is not None else self._src_dir

    valid = EssentialParameters(self.__class__.__name__, [self._dest_name])
    valid()
    dest_path = os.path.join(dir, (self._dest_name + ".%s" % self._format))

    if self._format == "tar":
        with tarfile.open(dest_path, "w") as tar:
            for file in files:
                arcname = (
                    os.path.join(self._dest_name, os.path.basename(file))
                    if self._create_dir
                    else os.path.basename(file)
                )
                tar.add(file, arcname=arcname)
    elif self._format == "zip":
        with zipfile.ZipFile(dest_path, "w") as zp:
            for file in files:
                arcname = (
                    os.path.join(self._dest_name, os.path.basename(file))
                    if self._create_dir
                    else os.path.basename(file)
                )
                zp.write(file, arcname=arcname)
    else:
        raise InvalidParameter(
            "'format' must set one of the followings [tar, zip]"
        )

def __repr__(self):
    return ("{}
{}
{}
Ud({}, {}, {})
{}
{}
".format(
        pi_check(self.global_phase),
        np.array_str(self.K1l),
        np.array_str(self.K1r),
        self.a, self.b, self.c,
        np.array_str(self.K2l),
        np.array_str(self.K2r)))

def _retrieve(self, query, format):
    if self.http_method == 'POST':
        request_method = 'POST'
    elif self.http_method == 'GET':
        request_method = 'GET'
    else:
        request_method = 'POST'  # Default to POST for large SLDs

    if request_method == 'POST':
        url, data = self._query_data(query, format)
    else:
        url = self._query_url(query, format)
        data = None

    if self.lock:
        with self.lock():
            resp = self.http_client.open(url, data=data)
    else:
        resp = self.http_client.open(url, data=data)
    self._check_resp(resp)
    return resp

def __get__(self, instance, owner):
    # type: (typing.Optional['HasTraits'], 'MetaType') -> typing.Any
    self._assert_have_field_name()
    if instance is None:
        # called from class, not an instance
        return self
    if self.field_name not in instance.__dict__:
        if isinstance(self.default, types.FunctionType):
            default = self.default()
        else:
            default = self.default
        instance.__dict__[self.field_name] = default
    if self.required and self.field_name not in instance.__dict__:
        raise AttributeError(f"{self.field_name} is required but not set.")
    return instance.__dict__[self.field_name]

def iterCoordinates(self, micrograph=None):
    """ Iterate over the coordinates associated with a micrograph.
    If micrograph=None, the iteration is performed over the whole set of coordinates.
    """
    if micrograph is None:
        micId = None
    elif isinstance(micrograph, int):
        micId = micrograph
    elif isinstance(micrograph, Micrograph):
        micId = micrograph.getObjId()
    else:
        raise Exception('Invalid input micrograph of type %s' % type(micrograph))

    if micId is None:
        yield from self
    else:
        yield from (coord for coord in self if coord.getMicId() == micId)

def _create_checkpoint_manager(self):
