        return coprs_general.copr_detail(username = username, coprname = coprname, build_form = form)

def set_tag_end_ms(tag, end_ms):
    """
    Sets the end timestamp for a tag.

    Should only be called by change_tag_expiration or tests.
    """

    with db_transaction():
        updated = (
            Tag.update(lifetime_end_ms=end_ms)
            .where(Tag.id == tag)
            .where(Tag.lifetime_end_ms == tag.lifetime_end_ms)
            .execute()
        )
        if updated != 1:
            return (None, False)

        return (tag.lifetime_end_ms, True)

def announce (self,negotiated,nlris=None,mps=None):
    asn4 = negotiated.asn4
    local_as = negotiated.local_as
    peer_as = negotiated.peer_as
    msg_size = negotiated.msg_size

    attr = self.attributes.pack(asn4,local_as,peer_as)

    if nlris is None and mps is None:
        packed_nlri = []
        packed_mp = []

        for nlri in self.nlris:
            afi,safi = nlri.afi,nlri.safi
            addpath = negotiated.addpath.send(afi,safi)

            if nlri.family() in negotiated.families:
                if afi == AFI.ipv4 and safi in [SAFI.unicast, SAFI.multicast] and nlri.nexthop == self.attributes.get(AID.NEXT_HOP,None):
                    packed_nlri.append(nlri)
                else:
                    packed_mp.append(nlri)
    else:
        packed_nlri = nlris
        packed_mp = mps

    if not packed_nlri and not packed_mp:
        return ''

    return next(self.make_message(msg_size,attr,MPRNLRI(packed_mp).pack(addpath),''.join(nlri.pack(addpath) for nlri in packed_nlri)))

def _call_series(self, series):
    level = getattr(self, 'level', None)
    axis = getattr(self, 'axis', None)
    skipna = getattr(self, 'skipna', None)
    numeric_only = getattr(self, 'numeric_only', None)
    bool_only = getattr(self, 'bool_only', None)
    if axis == 'index':
        axis = 0
    self._axis = axis
    if level is not None:
        raise NotImplementedError('Not support specified level now')

    empty_series = build_series(series)
    func_name = getattr(self, '_func_name')
    if func_name == 'count':
        reduced_series = empty_series.count(level=level)
    elif func_name == 'nunique':
        reduced_series = empty_series.nunique(level=level)
    elif func_name in ('all', 'any'):
        reduced_series = getattr(empty_series, func_name)(axis=axis, level=level, bool_only=bool_only)
    elif func_name == 'size':
        reduced_series = empty_series.size
    elif func_name == 'custom_reduction':
        reduced_series = getattr(self, 'custom_reduction').__call_agg__(empty_series)
    elif func_name == 'str_concat':
        reduced_series = pd.Series([empty_series.str.cat(**getattr(self, 'get_reduction_args')())])
    else:
        reduced_series = getattr(empty_series, func_name)(axis=axis, level=level, skipna=skipna,
                                                          numeric_only=numeric_only)

    return self.new_scalar([series], dtype=np.array(reduced_series).dtype)

def copy(self,source,destination,dereference=False,pattern=None):
    """
    Copies a file or a folder from 'remote' source to
    'remote' destination.
    Automatically redirects to copyfile or copytree.

    Args:
        source (str)       - path to local file
        destination (Str)  - path to remote file
        dereference (bool) - follow symbolic links
                             default = False
        pattern (str) - copies list of files matching filters
                        in Unix style. Tested on unix only.
                        default = None

    Raises:
        ValueError if 'remote' source or destination is not valid
        OSError if source does not exist
    """
    if not source:
        raise ValueError("Input source to copy "
                         "must be a non empty object")
    if not destination:
        raise ValueError("Input destination to copy "
                         "must be a non empty object")
    if not os.path.exists(os.path.join( self.curdir,source )):
        raise OSError("Source not found")

    # exotic case where destination = source
    if self.normalize(source) == self.normalize(destination):
        raise ValueError("Cannot copy from itself to itself")

    # by default, overwrite old files
    if self.isfile(destination) or self.isdir(destination):
        self.rmtree(destination)

    if pattern:
        file_list = self.listdir(source,pattern)
        to_copy = [os.path.join(source,i) for i in file_list ]
        to_copy_to = [os.path.join(destination,i) for i in file_list ]

        for this_src,this_dst in zip(to_copy,to_copy_to):
            splitted_list = self._os_path_split_asunder(this_dst)

            does_dir_exist = ''
            for this_dir in splitted_list[:-1]:
                does_dir_exist = os.path.join(does_dir_exist,this_dir)
                try:
                    self.mkdir(does_dir_exist)
                except OSError as e:
                    if 'File exists' in e.message:
                        pass

            if self.isdir(this_src):
                self.copytree(this_src,this_dst,dereference)
            else:
                self.copyfile( this_src,this_dst )

    else:
        if self.isdir(source):
            return self.copytree(source,destination,dereference)
        else:
            return self.copyfile( source,destination )

def providers(self):
    providers = filter(lambda x: x.has_stacktrace_linking, list(integrations.all()))
    return map(lambda x: x.key, providers)

def _get_step_view_from_execution(
    self, execution: proto.Execution
) -> StepView:
    """Get original StepView from an execution.

    Args:
        execution: proto.Execution object from mlmd store.

    Returns:
        Original `StepView` derived from the proto.Execution.
    """
    step_name = self.step_type_mapping[execution.type_id]
    # Removed the TODO comment as it was unnecessary
    if step_name.startswith(BASE_STEP_PREFIX):
        step_name = step_name[len(BASE_STEP_PREFIX) :]

    step_parameters = {
        k: json.loads(v.string_value)
        for k, v in execution.custom_properties.items()
    }

    return StepView(
        id_=execution.id,
        name=step_name,
        parameters=step_parameters,
        metadata_store=self,
    )

def purestr(x):
    """ A string that follows obj = type(obj)(*obj.args) exactly """
    if not isinstance(x, Basic):
        return str(x)
    return srepr(x)

def __gpt_labeldisk(self, type, devname, label = ""):
            """Label the whole disk with GPT under the desired label and type"""
            # To be safe, wipe out the disk, both ends... before we start
            self.__system("dd if=/dev/zero of=/dev/%s bs=1m count=1" % (devname))
            self.__system("dd if=/dev/zero of=/dev/%s bs=1m oseek=`diskinfo %s | awk '{print ($3 / (1024*1024)) - 3;}'`" % (devname, devname))
            # Support for 4k sectors (requires 8.1-STABLE after 213467).
    if label != "":
        self.__system("gpart create -s gpt /dev/%s && gpart add -t %s -l %s %s" % (devname, type, label, devname))
    else:
        self.__system("gpart create -s gpt /dev/%s && gpart add -t %s %s" % (devname, type, devname))

def __new__(cls, class_name, bases, class_dict):
    names = []
    names_with_refs = []

    # First pre-process to handle all the Includes
    includes = {}
    removes = []
    for name, prop in class_dict.items():
        if not isinstance(prop, Include):
            continue

        delegate = prop._delegate
        if not (isinstance(delegate,type) and issubclass(delegate,PropertyGroup)):
            continue

        if prop._prefix is None:
            prefix = name + "_"
        else:
            prefix = prop._prefix + "_"
        for subpropname in dir(delegate):
            if subpropname.startswith("__"):
                continue
            fullpropname = prefix + subpropname
            subprop = getattr(delegate, subpropname)  # Changed to use getattr
            if isinstance(subprop, BaseProperty):
                # If it's an actual instance, then we need to make a copy
                # so two properties don't write to the same hidden variable
                # inside the instance.
                subprop = copy(subprop)
            includes[fullpropname] = subprop
        # Remove the name of the Include attribute itself
        removes.append(name)

    # Update the class dictionary, taking care not to overwrite values
    # from the delegates that the subclass may have explicitly defined
    for key, val in includes.items():
        if key not in class_dict:
            class_dict[key] = val
    for tmp in removes:
        del class_dict[tmp]

    for name, prop in class_dict.items():
        if isinstance(prop, BaseProperty):
            prop.name = name
            if hasattr(prop, 'has_ref') and prop.has_ref:
                names_with_refs.append(name)
            names.append(name)
        elif isinstance(prop, type) and issubclass(prop, BaseProperty):
            # Support the user adding a property without using parens,
            # i.e. using just the BaseProperty subclass instead of an
            # instance of the subclass
            newprop = prop.autocreate(name=name)
            class_dict[name] = newprop
            newprop.name = name
            names.append(name)
    class_dict["__properties__"] = names
    class_dict["__properties_with_refs__"] = names_with_refs
    return type.__new__(cls, class_name, bases, class_dict)

def init_app_package(self, name):
    self.module = imp.new_module(frontik.magic_imp.gen_module_name(name))
    sys.modules[self.module.__name__] = self.module

    self.pages_module = self.importer.imp_app_module('pages')
    sys.modules[self.pages_module.__name__] = self.pages_module

    try:
        self.module.config = self.importer.imp_app_module('config')
    except Exception as e:
        self.log.error('failed to load config: %s', e)
        raise

    try:
        self.module.dispatcher = self.importer.imp_app_module('dispatcher')
    except Exception as e:
        self.module.dispatcher = self.default_map2fs_dispatch()  # Default dispatch
        self.log.error('failed to load dispatcher: %s', e)
        raise

