async def remove_schedules(self, ids: Iterable[str]) -> None:
    async for attempt in self._retry():
        with attempt:
            async with self._begin_transaction() as conn:
                delete: Delete | ReturningDelete[
                    Any
                ] = self._t_schedules.delete().where(
                    self._t_schedules.c.id.in_(ids)
                )
                if self._supports_update_returning:
                    delete_returning = delete.returning(self._t_schedules.c.id)
                    removed_ids: Iterable[str] = [
                        row[0]
                        for row in await self._execute(conn, delete_returning)
                    ]
                else:
                    await self._execute(conn, delete)
                    removed_ids = [id for id in ids if id not in removed_ids]

    for schedule_id in removed_ids:
        await self._event_broker.publish(ScheduleRemoved(schedule_id=schedule_id))

def test_json_schema():
    @validate_call
    def foo(a: int, /, b: int):
        return f'{a}, {b}'

    assert foo(1, 2) == '1, 2'
    assert foo(1, b=2) == '1, 2'
    assert foo(1) == '1, None'
    assert TypeAdapter(foo).json_schema() == {
        'type': 'object',
        'properties': {'a': {'title': 'A', 'type': 'integer'}, 'b': {'default': None, 'title': 'B', 'type': 'integer'}},
        'required': ['a'],
        'additionalProperties': False,
    }

    # assert foo(1, 2) == '1, 2'
    # assert TypeAdapter(foo).json_schema() == {
    #     'maxItems': 2,
    #     'minItems': 2,
    #     'prefixItems': [{'title': 'A', 'type': 'integer'}, {'title': 'B', 'type': 'integer'}],
    #     'type': 'array',
    # }

    # @validate_call
    # def foo(a: int, /, *, b: int, c: int):
    #     return f'{a}, {b}, {c}'

    # assert foo(1, b=2, c=3) == '1, 2, 3'
    # with pytest.raises(
    #     PydanticInvalidForJsonSchema,
    #     match=(
    #       'Unable to generate JSON schema for arguments validator '
    #       'with positional-only and keyword-only arguments'
    #     ),
    # ): 
    #     TypeAdapter(foo).json_schema()

    @validate_call
    def foo(*numbers: int) -> int:
        return sum(numbers)

    assert foo(1, 2, 3) == 6
    assert TypeAdapter(foo).json_schema() == {'items': {'type': 'integer'}, 'prefixItems': [], 'type': 'array'}

    @validate_call
    def foo(**scores: int) -> str:
        return ', '.join(f'{k}={v}' for k, v in sorted(scores.items()))

    assert foo(a=1, b=2) == 'a=1, b=2'
    assert TypeAdapter(foo).json_schema() == {
        'additionalProperties': {'type': 'integer'},
        'properties': {},
        'type': 'object',
    }

    @validate_call
    def foo(a: Annotated[int, Field(..., alias='A')]):
        return a

    assert foo(1) == 1
    assert TypeAdapter(foo).json_schema() == {
        'additionalProperties': False,
        'properties': {'A': {'title': 'A', 'type': 'integer'}},
        'required': ['A'],
        'type': 'object',
    }

def run(self, server, varargs, kwargs=None):
    if kwargs is None:
        kwargs = {}
    message = "%s\t" % str(server)
    response = None
    try:
        response = self.routine(*varargs, **kwargs)
        self.handle_response(response, message)
    except (CommError, KeyError, ValueError) as e:
        self.log_error(message, e)
        self.all_ok = False

    def log_error(self, message, error):
        sys.stderr.write(message + ("%s: %s\n" % (error.__class__.__name__, error)))

def make_tuplet_from_proportions_and_pair(proportions, (n, d)):
    '''Divide nonreduced fraction `(n, d)` according to `proportions`.

    Return container when no prolation is necessary::

        >>> tuplettools.make_tuplet_from_proportions_and_pair([1], (7, 16))
        {c'4..}

    Return fixed-duration tuplet when prolation is necessary::

        >>> tuplettools.make_tuplet_from_proportions_and_pair([1, 2], (7, 16))
        FixedDurationTuplet(7/16, [c'8, c'4])

    ::

        >>> tuplettools.make_tuplet_from_proportions_and_pair([1, 2, 4], (7, 16))
        FixedDurationTuplet(7/16, [c'16, c'8, c'4])

    ::

        >>> tuplettools.make_tuplet_from_proportions_and_pair([1, 2, 4, 1], (7, 16))
        FixedDurationTuplet(7/16, [c'16, c'8, c'4, c'16])

    ::

        >>> tuplettools.make_tuplet_from_proportions_and_pair([1, 2, 4, 1, 2], (7, 16))
        FixedDurationTuplet(7/16, [c'16, c'8, c'4, c'16, c'8])

    ::

        >>> tuplettools.make_tuplet_from_proportions_and_pair([1, 2, 4, 1, 2, 4], (7, 16))
        FixedDurationTuplet(7/16, [c'16, c'8, c'4, c'16, c'8, c'4])

    .. note:: function interprets `d` as tuplet denominator.

    Return tuplet or container.

    .. versionchanged:: 2.0
        renamed ``divide.pair()`` to
        ``tuplettools.make_tuplet_from_proportions_and_pair()``.
    '''
    from abjad.tools import tuplettools

    # check input
    proportions = mathtools.Ratio(proportions)
    assert proportions
    duration = durationtools.Duration(n, d)

    if len(proportions) == 1:
        if 0 < proportions[0]:
            try:
                return containertools.Container([notetools.Note(0, duration)])
            except AssignabilityError:
                return containertools.Container(notetools.make_notes(0, duration))
        elif proportions[0] < 0:
            try:
                return containertools.Container([resttools.Rest(duration)])
            except AssignabilityError:
                return containertools.Container(resttools.make_rests(duration))
        else:
            raise ValueError('no divide zero values.')

    if 1 < len(proportions):
        exponent = int(math.log(mathtools.weight(proportions), 2) - math.log(n, 2))
        denominator = int(d * 2 ** exponent)
        music = []
        for x in proportions:
            if not x:
                raise ValueError('no divide zero values.')
            if 0 < x:
                try:
                    music.append(notetools.Note(0, (x, denominator)))
                except AssignabilityError:
                    music.extend(notetools.make_notes(0, (x, denominator)))
            else:
                music.append(resttools.Rest((-x, denominator)))
        return tuplettools.FixedDurationTuplet(duration, music)

def Run(self, cmd_val):
  # type: (cmd_value__Argv) -> int
  attrs, offset = arg_def.ParseCmdVal('unset', cmd_val)
  n = len(cmd_val.argv)
  arg = arg_types.unset(attrs.attrs)

  for name in cmd_val.Rest():
    spid = cmd_val.arg_spids[offset]

    if arg.f:
      if name in self.funcs:
        del self.funcs[name]

    elif arg.v:
      if not self._UnsetVar(name, spid, False):
        return 1

    else:
      # proc_fallback: Try to delete var first, then func.
      if not self._UnsetVar(name, spid, True):
        return 1

  return 0

def baseLevel(runthis, timeout, knownPath, logPrefix, valgrind=False):
    if valgrind:
        runthis = (
            constructVgCmdList(errorCode=VALGRIND_ERROR_EXIT_CODE) +
            valgrindSuppressions(knownPath) +
          runthis)

    wantStack = True
    runinfo = timedRun.timed_run(runthis, timeout, logPrefix, wantStack)
    sta = runinfo.sta

    lev = JS_FINE
    issues = []
    sawAssertion = False

    if detect_malloc_errors.amiss(logPrefix):
        issues.append("malloc error")
        lev = max(lev, JS_MALLOC_ERROR)

    if valgrind and runinfo.rc == VALGRIND_ERROR_EXIT_CODE:
        issues.append("valgrind reported an error")
        lev = max(lev, JS_VG_AMISS)
        valgrindErrorPrefix = "==" + str(runinfo.pid) + "=="
    else:
        valgrindErrorPrefix = None

    with open(logPrefix + "-err.txt", "rb") as err:
        for line in err:
            assertion_info = detect_assertions.scanLine(knownPath, line)
            if assertion_info:
                issues.append(line.rstrip())
                lev = max(lev, JS_NEW_ASSERT_OR_CRASH)
                sawAssertion = assertion_info[0]
            if line.startswith("Assertion failure:"):
                sawAssertion = True
                lev = max(lev, JS_KNOWN_CRASH)
            if valgrindErrorPrefix and line.startswith(valgrindErrorPrefix):
                issues.append(line.rstrip())

    if sawAssertion:
        # Ignore the crash log, since we've already seen a new assertion failure.
        pass
    elif sta == timedRun.CRASHED:
        if detect_interesting_crashes.amiss(knownPath, logPrefix + "-crash.txt", True):
            issues.append("unknown crash")
            lev = max(lev, JS_NEW_ASSERT_OR_CRASH)
        else:
            issues.append("known crash")
            lev = max(lev, JS_KNOWN_CRASH)
    elif sta == timedRun.TIMED_OUT:
        issues.append("timed out")
        lev = max(lev, JS_TIMED_OUT)
    elif sta == timedRun.ABNORMAL and not (valgrind and runinfo.rc == VALGRIND_ERROR_EXIT_CODE):
        issues.append("abnormal exit")
        lev = max(lev, JS_ABNORMAL_EXIT)

    return (lev, issues, runinfo)

def load_configfile():
    defaults = {}
    for k in options:
        defaults[k] = options[k]['default']
    if sys.version_info < (3,0):
        print "Python 2"
        #Python 2.7
        for k, v in defaults.items():
            config.set({k: v})
    else:
        print "Python 3"
        #Python 3
        # config[SEC_GENERAL] = defaults
    if not os.path.exists(CONFIG_FILE):
        initialize_configfile()
    else:
        config.read(CONFIG_FILE)

def from_payload(cls, data, state):
    """
    Construct a response from the gateway payload.
    """

    # Reconstruct the component that was clicked
    clicked_component_id = data['data']['custom_id']
    clicked_component_payload = None
    for action_row in data['message'].get('components', list()):
        for component in action_row.get('components', list()):
            if component.get('custom_id', None) == clicked_component_id:
                clicked_component_payload = component
                break
        if clicked_component_payload is not None:
            break

    if clicked_component_payload is None:
        clicked_component_payload = {"custom_id": clicked_component_id}
    clicked_component_object = Button.from_dict(clicked_component_payload)

    # Make the response
    v = cls()
    v.data = data
    v._state = state
    v.component = clicked_component_object
    channel, guild = state._get_guild_channel(data)
    v.channel = channel
    v.guild = guild
    try:
        v.message = discord.Message(channel=channel, data=data['message'], state=state)
    except KeyError:
        v.message = discord.PartialMessage(channel=channel, id=int(data['message']['id']))
    if guild:
        v.user = discord.Member(data=data['member'], guild=guild, state=state)
    else:
        v.user = discord.User(data=data['user'], state=state)
    return v

def release_pgcon(self, dbname, conn, *, discard=False):
