def read(self):
    import warnings

    metadata_files = ("METADATA",  # wheel
                      "PKG-INFO")  # egg

    if self.entry_point and self.entry_point.dist:
        for metadata_file in metadata_files:
            try:
                return self.entry_point.dist.get_metadata(metadata_file)
            except Exception:
                pass

    warnings.warn('No package metadata found for package: {}'.format(self.entry_point.module_name))

def compile_Set(
        expr: qlast.Base, *, ctx: context.ContextLevel) -> irast.Base:
    if expr.elements:
        if len(expr.elements) == 1:
            return dispatch.compile(expr.elements[0], ctx=ctx)
        else:
            elements = flatten_set(expr)
            bigunion = qlast.BinOp(
                left=elements[0],
                right=elements[1],
                op=qlast.UNION_ALL
            )
            for el in elements[2:]:
                bigunion = qlast.BinOp(
                    left=bigunion,
                    right=el,
                    op=qlast.UNION_ALL
                )
            return dispatch.compile(bigunion, ctx=ctx)
    else:
        return irast.EmptySet()

def create_icon():
    """Creates FlexGet tasktray icon"""

    hover_text = "FlexGet"

    icon_file = os.path.join('flexget', 'ui', 'plugins', 'tasktray_win32', 'flexget.ico')

    def hello(sysTrayIcon):
        print "Hello World."

    def simon(sysTrayIcon):
        print "Hello Simon."

    menu_options = (('Say Hello', None, hello), ('Switch Icon', None, simon))

    def bye(sysTrayIcon):
        print 'Shutting down FlexGet...'
        sys.exit()  # Shutdown FlexGet

    SysTrayIcon(icon_file, hover_text, menu_options, on_quit=bye, default_menu_index=1)

def _compute_website_url(self):
    # TDE FIXME: clean this link.tracker strange stuff
    super(Slide, self)._compute_website_url()
    for slide in self:
        if slide.id:  # avoid to perform a slug on a not yet saved record in case of an onchange.
            base_url = slide.channel_id.get_base_url()
            # link_tracker is not in dependencies, so use it to shorten url only if installed.
            if self.env.registry.get('link.tracker'):
                url = self.env['link.tracker'].sudo().create({
                    'url': '%s/slides/slide/%s' % (base_url, slug(slide)),
                    'title': slide.name,
                }).short_url
            else:
                url = '%s/slides/slide/%s' % (base_url, slug(slide))
            slide.website_url = url

def notifyCall(event, date, number, caller, phone):
    if Standby.inStandby is None or config.plugins.FritzCall.afterStandby.value == "each":
        # Mute audio and/or stop tv/video
        mute_audio()  # Assuming a function to mute audio exists
        stop_tv_video()  # Assuming a function to stop tv/video exists
        if event == "RING":
            text = _("Incoming Call on %(date)s from\n---------------------------------------------\n%(number)s\n%(caller)s\n---------------------------------------------\nto: %(phone)s") % { 'date':date, 'number':number, 'caller':caller, 'phone':phone }
        else:
            text = _("Outgoing Call on %(date)s to\n---------------------------------------------\n%(number)s\n%(caller)s\n---------------------------------------------\nfrom: %(phone)s") % { 'date':date, 'number':number, 'caller':caller, 'phone':phone }
        print "[FritzCall] notifyCall:\n%s" %text
        Notifications.AddNotification(MessageBox, text, type=MessageBox.TYPE_INFO, timeout=config.plugins.FritzCall.timeout.value)
    elif config.plugins.FritzCall.afterStandby.value == "inList":
        #
        # if not yet done, register function to show call list
        global standbyMode
        if not standbyMode :
            standbyMode = True
            Standby.inStandby.onHide.append(callList.display)
        # add text/timeout to call list
        callList.add(event, date, number, caller, phone)
        print "[FritzCall] notifyCall: added to callList"
    else: # this is the "None" case
        print "[FritzCall] notifyCall: standby and no show"

def size(self):
    image, offset = font.rasterText(self.text, font.getDefaultFontFamily(), size=12)
    return image.shape[1], image.shape[0]

def requeue(self, queue=None):

  if not queue:
    if not self.data or not self.data.get("queue"):
      self.fetch(full_data=False)  # only fetch queue?
    queue = self.data["queue"]

  self.save_status("queued", queue=queue)

  # Between these two lines, jobs can become "lost" too.

  Queue(queue).enqueue_job_ids([str(self.id)])

def setUp(self):
    super().setUp()
    self._testkit_test_name = id_ = re.sub(
        r"^([^\.]+\.)*?tests\.", "", self.id()
    )
    self._check_subtests = False
    self._backend = new_backend()
    self.addCleanup(self._backend.close)
    self._driver_features = get_driver_features(self._backend)

    if self.required_features:
        self.skip_if_missing_driver_features(*self.required_features)

    response = self._backend.send_and_receive(protocol.StartTest(id_))
    if isinstance(response, protocol.SkipTest):
        self.skipTest(response.reason)

    response = self._backend.send_and_receive(protocol.StartTest(id_))
    if isinstance(response, protocol.SkipTest):
        self.skipTest(response.reason)
    elif isinstance(response, protocol.RunSubTests):
        self._check_subtests = True
    elif not isinstance(response, protocol.RunTest):
        raise Exception("Should be SkipTest, RunSubTests, or RunTest, "
                        "received {}: {}".format(type(response),
                                                 response))

