def map_objects_by_bounding_box(request):
    data = request.POST

    album_id = data.get("album_id") or None
    area_id = data.get("area_id") or None
    limit_by_album = data.get("limit_by_album") in ["true", True]

    qs = Photo.objects.all()

    ungeotagged_count = 0
    geotagged_count = 0
    if album_id is not None or area_id is not None:
        ungeotagged_count, geotagged_count = qs.get_album_photo_count_and_total_geotag_count(album_id, area_id)
        if album_id and limit_by_album:
            album = Album.objects.get(pk=album_id)
            album_photo_ids = list(album.photos.values_list("id", flat=True))
            for sa in album.subalbums.all():
                album_photo_ids += list(sa.photos.values_list("id", flat=True))
            qs = qs.filter(id__in=album_photo_ids)

    if data.get("sw_lat") and data.get("sw_lon") and data.get("ne_lat") and data.get("ne_lon"):
        bounding_box = (float(data.get("sw_lat")), float(data.get("sw_lon")), float(data.get("ne_lat")), float(data.get("ne_lon")))
        data = qs.get_geotagged_photos_list(bounding_box)
        data = {"photos": data, "geotagged_count": geotagged_count, "ungeotagged_count": ungeotagged_count}
    else:
        data = {"photos": [], "geotagged_count": 0, "ungeotagged_count": 0}

    return HttpResponse(json.dumps(data), content_type="application/json")

def url_join(base, url, allow_fragments=True):
    """Join a base URL and a possibly relative URL to form an absolute
    interpretation of the latter.

    :param base: the base URL for the join operation.
    :param url: the URL to join.
    :param allow_fragments: indicates whether fragments should be allowed.
    """
    if isinstance(base, tuple):
        base = url_unparse(base)
    if isinstance(url, tuple):
        url = url_unparse(url)

    base, url = normalize_string_tuple((base, url))
    s = make_literal_wrapper(base)

    if not base:
        return url
    if not url:
        return base

    bscheme, bnetloc, bpath, bquery, bfragment = 
        url_parse(base, allow_fragments=allow_fragments)
    scheme, netloc, path, query, fragment = 
        url_parse(url, bscheme, allow_fragments)
    if scheme != bscheme:
        return url
    if netloc:
        return url_unparse((scheme, netloc, path, query, fragment))
    netloc = bnetloc

    if path[:1] == s('/'): 
        return url_unparse((scheme, netloc, path, query, fragment))

    if not path:
        path = bpath
        if not query:
            query = bquery
        return url_unparse((scheme, netloc, path, query, fragment))
    segments = bpath.split(s('/'))[:-1] + path.split(s('/'))
    if segments[-1] == s('.'): 
        segments[-1] = s('')
    segments = [segment for segment in segments if segment != s('.')] 
    while 1:
        i = 1
        n = len(segments) - 1
        while i < n:
            if (segments[i] == s('..')
                and segments[i - 1] not in (s(''), s('..'))):
                del segments[i - 1:i + 1]
                break
            i += 1
        else:
            break
    if segments == [s(''), s('..')]:
        segments[-1] = s('')
    elif len(segments) >= 2 and segments[-1] == s('..'):
        segments[-2:] = [s('')]
    return url_unparse((scheme, netloc, s('/').join(segments), query, fragment))

def assemble_dephosphorylation(stmt):
    sub_str = assemble_agent_str(stmt.sub)
    if stmt.enz is not None:
        enz_str = assemble_agent_str(stmt.enz)
        stmt_str = enz_str + ' dephosphorylates ' + sub_str
    else:
        stmt_str = sub_str + ' is dephosphorylated'

    if stmt.mod_pos is None:
        if stmt.mod != 'Phosphorylation':
            mod_str = 'on ' + abbrev_word[stmt.mod]
        else:
            mod_str = ''
    else:
        mod_str = 'on ' + abbrev_letter[stmt.mod] + str(stmt.mod_pos)
    stmt_str += ' ' + mod_str
    return make_sentence(stmt_str)

def process_transaction(self, data: bytes):
    """
    Validates the POST Request from Client, and publishes it to Witnesses
    :param data: binary encoded JSON data from the user's POST request
    :return: A dictionary indicating the status of Masternode's attempt to publish the request to witnesses
    """
    # 1) Validate transaction size
    if not self.__validate_transaction_length(data):
        return {'error': TX_STATUS['INVALID_TX_SIZE']}
    # 2) De-serialize data
    try:
        d = self.serializer.deserialize(data)
    except Exception as e:
        print("in Exception of process_transaction")
        return {'error': TX_STATUS['SERIALIZE_FAILED'].format(e)}

    # Validate transaction fields
    try:
        TestNetTransaction.validate_tx_fields(d)
    except Exception as e:
        print(e)
        return {'error': TX_STATUS['INVALID_TX_FIELDS'].format(e)}

    # Add timestamp and UUID
    # d['metadata']['timestamp'] = self.time_client.request(NTP_URL, version=3).tx_time
    d['metadata']['timestamp'] = time.time()  # INSECURE, FOR DEMO ONLY
    d['metadata']['uuid'] = str(uuid.uuid4())

    payload_binary = JSONSerializer.serialize(d['payload'])
    if not ED25519Wallet.verify(d['payload']['from'], payload_binary, d['metadata']['signature']):
        print('masternode: fail point 2')
    else:
        print('masternode validated transaction')

    return self.publish_req(d)

def claimMahJongg(self, player, concealedMelds, withDiscard):
    # Check content of concealedMelds: does the player actually have those tiles and is it really mah jongg?
    ignoreDiscard = withDiscard
    for part in concealedMelds.split():
        meld = Meld(part)
        if not all(tile in player.concealedTiles for tile in meld.pairs):
            print 'concealedMelds:', concealedMelds
            print 'meld:', meld
            msg = 'claimMahJongg: Player does not really have the required tiles for meld %s' % meld
            self.sendAbortMessage(msg)
            return
        for pair in meld.pairs:
            if pair == ignoreDiscard:
                ignoreDiscard = None
            else:
                player.concealedTiles.remove(pair)
        player.concealedMelds.append(meld)
    if player.concealedTiles:
        msg='claimMahJongg: Player did not pass all concealed tiles to server'
        self.sendAbortMessage(msg)
    self.game.winner = player
    self.tellAll(player, 'declaredMahJongg', source=concealedMelds, lastTile=player.lastTile, withDiscard=withDiscard)
    self.endHand()

def __call__(self, data, **kwargs):
    columnIndex = self._get_columnIndex(data)

    # First, determine whether data has a multilevel index (either gen2 or gen3)
    is_multiLevel = isinstance(data, MultilevelParquetTable) or isinstance(columnIndex, pd.MultiIndex)

    # Simple single-level column index, gen2
    if isinstance(data, ParquetTable) and not is_multiLevel:
        columns = self.columns
        df = data.toDataFrame(columns=columns)
        valDict = {k: f._func(df) for k, f in self.funcDict.items()}

    # Multilevel index, gen2 or gen3
    if is_multiLevel:
        columns = self.multilevelColumns(data, columnIndex=columnIndex)

        if isinstance(data, MultilevelParquetTable):
            # Read data into memory the gen2 way
            df = data.toDataFrame(columns=columns, droplevels=False)
        elif isinstance(data, DeferredDatasetHandle):
            # Read data into memory the gen3 way
            df = data.get(parameters={"columns": columns})

        valDict = {}
        for k, f in self.funcDict.items():
            try:
                subdf = f._setLevels(
                    df[f.multilevelColumns(data, returnTuple=True, columnIndex=columnIndex)]
                )
                valDict[k] = f._func(subdf)
            except Exception:
                raise
                valDict[k] = f.fail(subdf)

    # non-multilevel, gen3
    elif isinstance(data, DeferredDatasetHandle):
        columns = self.columns
        df = data.get(parameters={"columns": columns})
        valDict = {k: f._func(df) for k, f in self.funcDict.items()}

    try:
        valDf = pd.concat(valDict, axis=1)
    except TypeError:
        print([(k, type(v)) for k, v in valDict.items()])
        raise

    if kwargs.get('dropna', False):
        valDf = valDf.dropna(how='any')

    return valDf

def get(self, request):
    # Gather the version numbers from all installed Django apps
    installed_apps = {}
    for app_config in apps.get_app_configs():
        app = app_config.module
        version = getattr(app, "VERSION", getattr(app, "__version__", None))
        if version:
            if isinstance(version, tuple):
                version = ".".join(str(n) for n in version)
        installed_apps[app_config.name] = version
    installed_apps = dict(sorted(installed_apps.items()))

    # Gather installed plugins
    plugins = {}
    for plugin_name in settings.PLUGINS:
        plugin_name = plugin_name.rsplit(".", 1)[-1]
        plugin_config = apps.get_app_config(plugin_name)
        plugins[plugin_name] = getattr(plugin_config, "version", None)
    plugins = dict(sorted(plugins.items()))

    # Gather Celery workers
    workers = celery_app.control.inspect().active()  # list or None
    worker_count = len(workers) if workers is not None else 0

    return Response(
        {
            "django-version": DJANGO_VERSION,
            "installed-apps": installed_apps,
            "nautobot-version": settings.VERSION,
            "plugins": plugins,
            "python-version": platform.python_version(),
            "celery-workers-running": worker_count,
        }
    )

