def __get_k8s_containers(self, job_wrapper):
    """Fills in all required for setting up the docker containers to be used, including setting a pull policy if
       this has been set.
    """
    k8s_container = {
        "name": self.__get_k8s_container_name(job_wrapper),
        "image": self._find_container(job_wrapper).container_id,
        "command": ["/bin/bash", "-c", job_wrapper.runner_command_line],
        "workingDir": job_wrapper.working_directory,
        "volumeMounts": [{
            "mountPath": self.runner_params['k8s_persistent_volume_claim_mount_path'],
            "name": self._galaxy_vol_name
        }]
    }

    if job_wrapper.shell:
        k8s_container["command"] = ["/bin/bash", "-c", job_wrapper.runner_command_line]

    resources = self.__get_resources(job_wrapper)
    if resources:
        k8s_container['resources'] = resources

    if self._default_pull_policy:
        k8s_container["imagePullPolicy"] = self._default_pull_policy

    return [k8s_container]

def _stream_logs_to_output(self) -> None:
    if not self.cli:
        raise Exception("The 'cli' should be initialized before!")
    if not self.service:
        raise Exception("The 'service' should be initialized before!")
    logs = self.cli.service_logs(
        self.service['ID'], follow=True, stdout=True, stderr=True, is_tty=self.tty
    )
    line = ''
    while True:
        try:
            log = next(logs)
        except StopIteration:
            # If the service log stream terminated, stop fetching logs further.
            break
        else:
            try:
                log = log.decode()
            except UnicodeDecodeError:
                continue
            if log == '\n':
                self.log.info(line)
                line = ''
            else:
                line += log
    # flush any remaining log stream
    if line:
        self.log.info(line)

def get(method, hmc, uri, uri_parms, logon_required):
    # pylint: disable=unused-argument
    """Operation: List Image Activation Profiles (requires classic
    mode)."""
    cpc_oid = uri_parms[0]
    query_str = uri_parms[1]
    try:
        cpc = hmc.cpcs.lookup_by_oid(cpc_oid)
    except KeyError:
        new_exc = InvalidResourceError(method, uri)
        new_exc.__cause__ = None
        raise new_exc  # zhmcclient_mock.InvalidResourceError
    if cpc.dpm_enabled:
        raise ValueError('DPM is enabled, cannot list image activation profiles.')
    result_profiles = []
    filter_args = parse_query_parms(method, uri, query_str)
    for profile in cpc.image_activation_profiles.list(filter_args):
        result_profile = {}
        for prop in profile.properties:
            if prop in ('element-uri', 'name'):
                result_profile[prop] = profile.properties[prop]
        result_profiles.append(result_profile)
    return {'image-activation-profiles': result_profiles}

def getMemberNames(self):
    assert self.isCollection
    childlist = set()
    l = len(self.path)
    for f in self.provider.files:
        if f.startswith(self.path):
            p = f[l:]
            if '/' in p:
                p = p.split('/')[0]
            childlist.add(p)
        else:
            if childlist:
                break
    return list(childlist)

def getDevice(self, dev, cls=None):
    """Return a device *dev* from the current setup.

    If *dev* is a string, the corresponding device will be looked up or
    created, if necessary.

    *cls* gives a class, or tuple of classes, that *dev* needs to be an
    instance of.
    """
    if isinstance(dev, str):
        if dev in self.devices:
            dev = self.devices[dev]
        elif dev in self.configured_devices:
            dev = self.createDevice(dev)
        else:
            raise ConfigurationError(
                'device %r not found in configuration' % dev)
    if not isinstance(dev, cls if isinstance(cls, tuple) else (cls or Device)):
        raise UsageError('dev must be a %s' % (cls if isinstance(cls, tuple) else (cls or Device)).__name__)
    return dev

