def get_constraint(metric: Metric, bound: float, relative: bool) -> List[OutcomeConstraint]:
    return [
        OutcomeConstraint(
            metric=metric, op=ComparisonOp.GEQ, bound=bound, relative=relative
        )
    ]

def __call__(self, acquire):
    """
    Calling the pipeline by providing the first ``acquire`` step.

    It might look like a typeclass,
    but typeclass support is not yet enabled in our project.
    So, it is just a bunch of ``if`` statements for now.
    """
    if isinstance(acquire, IOResult):
        return acquire.bind(self._ioresult_pipeline)
    elif isinstance(acquire, RequiresContextIOResult):
        return acquire.bind(self._reader_ioresult_pipeline)
    elif isinstance(acquire, RequiresContextFutureResult):
        return acquire.bind_async(self._future_pipeline)
    return acquire.bind_async(self._future_pipeline)

def _perform_login(self, request: HttpRequest) -> HttpResponse:
    code = request.GET.get("code")
    user_data = self._fetch_user_data(code)
    if user_data is None:
        log.warning("Unable to log in due to problem on Sentry", exc_info=True)
        return redirect(f"{settings.CODECOV_DASHBOARD_URL}/login")

    # Verify `id_token` by decoding the JWT using our shared secret
    id_token = user_data.get("id_token")
    if not id_token:
        log.warning("No id_token found in user data")
        return redirect(f"{settings.CODECOV_DASHBOARD_URL}/login")
    try:
        decoded_token = jwt.decode(id_token, settings.SHARED_SECRET, algorithms=["HS256"])
    except jwt.ExpiredSignatureError:
        log.warning("JWT has expired")
        return redirect(f"{settings.CODECOV_DASHBOARD_URL}/login")
    except jwt.InvalidTokenError:
        log.warning("Invalid JWT token")
        return redirect(f"{settings.CODECOV_DASHBOARD_URL}/login")

    current_user = self._login_user(request, user_data)

    # TEMPORARY: we're assuming a single owner for the time being since there's
    # no supporting UI to select which owner you'd like to view
    owner = current_user.owners.first()
    if owner is not None:
        service = get_short_service_name(owner.service)
        return redirect(f"{settings.CODECOV_DASHBOARD_URL}/{service}")
    else:
        # user has not connected any owners yet
        return redirect(f"{settings.CODECOV_DASHBOARD_URL}/sync")

def _addExtraCfg(self, cmd, devices=tuple(), use_lvmpolld=True):
    newcmd = [constants.EXT_LVM, cmd[0]]

    if devices:
        dev_filter = _buildFilter(devices)
    else:
        dev_filter = self._getCachedFilter()

    conf = _buildConfig(
        dev_filter=dev_filter,
        use_lvmpolld="1" if use_lvmpolld else "0")
    newcmd += ["--config", conf]

    if len(cmd) > 1:
        newcmd += cmd[1:]

    return newcmd

def add_flair(paragraphs: List[str], gens: Dict[str, Any]) -> List[str]:

    # roll the dice and see what kind of flair we should add, if any
    results = []

    flair = get_flair_gen(len(paragraphs))

    for i in range(len(paragraphs)):
        key = flair[i]
        if key == "None":
            txt = paragraphs[i]
        elif key == "italic":
            txt = add_md("*", paragraphs[i])
        elif key == "bold":
            txt = add_md("**", paragraphs[i])
        elif key == "strike-thru":
            txt = add_md("~~", paragraphs[i])
        elif key == "quoted":
            txt = ">" + paragraphs[i]
        elif key == "quote-block":
            txt = paragraphs[i] + "\n" + next(gens["quote-blocks"])
        elif key == "inline-code":
            txt = paragraphs[i] + "\n" + next(gens["inline-code"])
        elif key == "code-block":
            txt = paragraphs[i] + "\n" + next(gens["code-blocks"])
        elif key == "math":
            txt = paragraphs[i] + "\n" + next(gens["maths"])
        elif key == "list":
            txt = paragraphs[i] + "\n" + next(gens["lists"])
        elif key == "emoji":
            txt = add_emoji(paragraphs[i], next(gens["emojis"]))
        elif key == "link":
            txt = add_link(paragraphs[i], next(gens["links"]))
        elif key == "picture":
            txt = paragraphs[i] + "\n" + next(gens["pictures"])

        results.append(txt)

    return results

def get_file(self,target_path,host_path,note=None):
    """Copy a file from the target machine to the host machine

    @param target_path: path to file in the target
    @param host_path:   path to file on the host machine (e.g. copy test)
    @param note:        See send()

    @type target_path: string
    @type host_path:   string

    @return:           ???
    @rtype:            string
    """
    filename = os.path.basename(target_path)
    cfg = self.cfg
    self._handle_note(note)
    os.system(f'docker cp {target_path} {host_path}/{cfg["build"]["build_id"]}_{filename}')
    self._handle_note_after(note=note)
    return os.path.join(host_path,'{0}_'.format(cfg['build']['build_id']) + filename)

def __call__(self, *args, **kwargs):
    name_to_find = self.func.__name__
    log.debug('All active plugin objects %s ' % get_all_active_plugin_objects())
    for obj in get_all_active_plugin_objects():
        matching_members = getmembers(obj, self.method_filter)
        log.debug('Matching members %s -> %s' % (obj, matching_members))
        if matching_members:
            name, func = matching_members[0]
            if self.raw:  # override and gives the request directly
                response = func(request, **kwargs)
            elif self.form_param:
                content = request.forms.get(self.form_param)
                if content is None:
                    raise Exception("Received a request on a webhook with a form_param defined, "
                                    "but that key ({}) is missing from the request.".format(self.form_param))
                try:
                    content = loads(content)
                except ValueError:
                    log.debug('The form parameter is not JSON, return it as a string')
                response = func(content, **kwargs)
            else:
                data = try_decode_json(request)
                if not data:
                    if hasattr(request, 'forms'):
                        data = dict(request.forms)  # form encoded
                    else:
                        data = request.body.read().decode()
                response = func(data, **kwargs)
            return response if response else ''  # assume None as an OK response (simplifies the client side)

    raise Exception('Problem finding back the correct Handler for func %s' % name_to_find)

def filter_tasks(self, tasks):
    """ Reduce the tasks based on the user selectable PIDS parameter.

    Returns a reduced list or the full list if config.PIDS not specified.
    """
    try:
        if self._config.PID:
            pidlist = [int(p) for p in self._config.PID.split(',')]
            newtasks = [t for t in tasks if t.UniqueProcessId in pidlist]
            tasks = newtasks
    except (ValueError, TypeError):
        print("Warning: Invalid PID format or type. Using full task list.")

    return tasks

def get_hash_algo(_namespace):
  """Return hash algorithm class to use when uploading to given |namespace|."""
  return hashlib.sha256

def _array_indexing(array, key, key_dtype, axis):
    """Index an array or scipy.sparse consistently across NumPy version."""
    if issparse(array):
        if key_dtype == "bool":
            key = np.asarray(key)
    if isinstance(key, tuple):
        key = list(key)
    return array[key] if axis == 0 else array[:, key]

def termdef(term):
    types = set(o.id for o in term.objects(RDF.type))
    is_class = types & CLASS_TYPES
    is_prop = types & PROP_TYPES
    if not is_class and not is_prop:
        return None
    if is_class:
        equiv = OWL.equivalentClass
        subof = RDFS.subClassOf
    else:
        equiv = OWL.equivalentProperty
        subof = RDFS.subPropertyOf
    target_candidates = term.value(OWL.sameAs) or term.value(equiv) or term.value(subof)
    target_term = target_candidates[0] if target_candidates else None

    curie = unicode((target_term or term).qname())
    if is_class:
        return curie

    range_type = term.value(RDFS.range)
    range_iri = range_type and range_type.id
    if range_iri and range_iri.startswith(XSD) or range_iri == RDFS.Literal:
        datatype = range_type.qname()
    elif OWL.DatatypeProperty in types:
        datatype = False
    else:
        datatype = None

    if types & {RDF.Property, OWL.FunctionalProperty}:
        container = None
    elif range_iri == RDF.List:
        container = "@list"
    else:
        container = None

    reverse = None if target_term else term.value(OWL.inverseOf)
    if reverse or datatype or container:
        if reverse:
            dfn = {"@reverse": unicode(reverse.qname())}
        else:
            dfn = {"@id": curie}
        if datatype:
            dfn["@type"] = datatype
        elif datatype is False:
            dfn["@language"] = None
        if container:
            dfn["@container"] = container
        return dfn
    else:
        return curie

def _setup_jobs(self, job_names, skip_missing):
    """
    Create a solver job list from given list of job names

    :param list job_names: list of package,pattern,group names
    :param bool skip_missing: continue or raise if job selection failed

    :return: list of :class:`Pool.selection()` objects

    :rtype: list
    """
    jobs = []
    for job_name in job_names:
        if job_name == 'apt-get':
            job_name = 'apt'
        selection_name = self.solv.Selection.SELECTION_NAME
        selection_provides = self.solv.Selection.SELECTION_PROVIDES
        selection = self.pool.select(
            job_name, selection_name | selection_provides
        )
        if selection.flags & self.solv.Selection.SELECTION_PROVIDES:
            log.info('--> Using capability match for {0}'.format(job_name))
        if selection.isempty():
            if skip_missing:
                log.info(
                    '--> Package {0} not found: skipped'.format(job_name)
                )
            else:
                raise KiwiSatSolverJobError(
                    'Package {0} not found'.format(job_name)
                )
        else:
            jobs += selection.jobs(self.solv.Job.SOLVER_INSTALL)

    return jobs

def get_widget_instance_dict(self, customization_args, context_params,
                             kvps_only=False):
    """Gets a dict representing a parameterized widget.

    If kvps_only is True, then the value for params in the result is
    a list of key-value pairs. Otherwise it is a dict, formatted as:

        {PARAM_NAME: {'value': PARAM_VALUE, 'obj_type': PARAM_OBJ_TYPE}}.
    """

    param_dict = {}
    for param in self.params:
        param_dict[param.name] = {
            'value': params.get(param.name, param.value),
            'obj_type': param.obj_type,
            'choices': param.choices,
        }

    if kvps_only:
        for param in param_dict:
            param_dict[param] = param_dict[param]['value']

    result = {
        'name': self.name,
        'category': self.category,
        'description': self.description,
        'id': self.id,
        'raw': self.get_raw_code(customization_args, context_params),
        'params': param_dict,
    }

    if self.type == feconf.INTERACTIVE_PREFIX:
        result['handlers'] = [h.to_dict() for h in self.handlers]
        for idx, handler in enumerate(self.handlers):
            result['handlers'][idx]['rules'] = dict((
                rule_cls.description,
                {'classifier': rule_cls.__name__}
            ) for rule_cls in handler.rules)

    return result

