def multicolumn_condition_partial(
    engine: Type[ExecutionEngine],
    partial_fn_type: Optional[Union[str, MetricPartialFunctionTypes]] = None,
    **kwargs,
):
    """Provides engine-specific support for authoring a metric_fn with a simplified signature. A
    multicolumn_condition_partial must provide a map function that evaluates to a boolean value; it will be used to
    provide supplemental metrics, such as the unexpected_value count, unexpected_values, and unexpected_rows.

    A metric function that is decorated as a multicolumn_condition_partial will be called with the engine-specific
    column_list type and any value_kwargs associated with the Metric for which the provider function is being declared.

    Args:
        engine:
        partial_fn_type:
        **kwargs:

    Returns:
        An annotated metric_function which will be called with a simplified signature.

    """
    domain_type = MetricDomainTypes.MULTICOLUMN
    if issubclass(engine, PandasExecutionEngine):
        if partial_fn_type is None:
            partial_fn_type = MetricPartialFunctionTypes.MAP_CONDITION_SERIES
        partial_fn_type = MetricPartialFunctionTypes(partial_fn_type)
        if partial_fn_type not in [MetricPartialFunctionTypes.MAP_CONDITION_SERIES]:
            raise ValueError(
                "PandasExecutionEngine only supports map_condition_series for multicolumn_condition_partial partial_fn_type"
            )

        def wrapper(metric_fn: Callable):
            @metric_partial(
                engine=engine,
                partial_fn_type=partial_fn_type,
                domain_type=domain_type,
                **kwargs,
            )
            @wraps(metric_fn)
            def inner_func(
                cls,
                execution_engine: PandasExecutionEngine,
                metric_domain_kwargs: Dict,
                metric_value_kwargs: Dict,
                metrics: Dict[str, Any],
                runtime_configuration: Dict,
            ):
                (
                    df,
                    compute_domain_kwargs,
                    accessor_domain_kwargs,
                ) = execution_engine.get_compute_domain(
                    domain_kwargs=metric_domain_kwargs, domain_type=domain_type
                )

                column_list = accessor_domain_kwargs["column_list"]

                for column_name in column_list:
                    if column_name not in metrics["table.columns"]:
                        raise ge_exceptions.ExecutionEngineError(
                            message=f'Error: The column "{column_name}" in BatchData does not exist.'
                        )

                meets_expectation_series = metric_fn(
                    cls,
                    df[column_list],
                    **metric_value_kwargs,
                    _metrics=metrics,
                )
                return (
                    ~meets_expectation_series,
                    compute_domain_kwargs,
                    accessor_domain_kwargs,
                )

            return inner_func

        return wrapper

    elif issubclass(engine, SqlAlchemyExecutionEngine):
        if partial_fn_type is None:
            partial_fn_type = MetricPartialFunctionTypes.MAP_CONDITION_FN
        partial_fn_type = MetricPartialFunctionTypes(partial_fn_type)
        if partial_fn_type not in [MetricPartialFunctionTypes.MAP_CONDITION_FN]:
            raise ValueError(
                "SqlAlchemyExecutionEngine only supports map_condition_fn for multicolumn_condition_partial partial_fn_type"
            )

        def wrapper(metric_fn: Callable):
            @metric_partial(
                engine=engine,
                partial_fn_type=partial_fn_type,
                domain_type=domain_type,
                **kwargs,
            )
            @wraps(metric_fn)
            def inner_func(
                cls,
                execution_engine: SqlAlchemyExecutionEngine,
                metric_domain_kwargs: Dict,
                metric_value_kwargs: Dict,
                metrics: Dict[str, Any],
                runtime_configuration: Dict,
            ):
                (
                    selectable,
                    compute_domain_kwargs,
                    accessor_domain_kwargs,
                ) = execution_engine.get_compute_domain(
                    domain_kwargs=metric_domain_kwargs, domain_type=domain_type
                )

                column_list = accessor_domain_kwargs["column_list"]

                for column_name in column_list:
                    if column_name not in metrics["table.columns"]:
                        raise ge_exceptions.ExecutionEngineError(
                            message=f'Error: The column "{column_name}" in BatchData does not exist.'
                        )

                sqlalchemy_engine: sa.engine.Engine = execution_engine.engine

                column_select = [sa.column(column_name) for column_name in column_list]
                dialect = execution_engine.dialect_module
                expected_condition = metric_fn(
                    cls,
                    column_select,
                    **metric_value_kwargs,
                    _dialect=dialect,
                    _table=selectable,
                    _sqlalchemy_engine=sqlalchemy_engine,
                    _metrics=metrics,
                )

                unexpected_condition = sa.not_(expected_condition)
                return (
                    unexpected_condition,
                    compute_domain_kwargs,
                    accessor_domain_kwargs,
                )

            return inner_func

        return wrapper

    else:
        raise ValueError("Unsupported engine for multicolumn_condition_partial")

def json(self, time=DEFAULT_TIME, **kwargs):
    try:
        # unit needs to be passed for chart_inline
        data = self.read(time=time)
        data.update({'unit': self.unit})
        return json.dumps(data, **kwargs)
    except KeyError:
        # Improved error handling
        return {'error': 'Key not found in data'}

def __start_non_classic(self):
    # Autoconnect to a host
    if self.config["autoconnect"]:

        def update_connection_manager():
            if not self.connectionmanager.running:
                return
            self.connectionmanager.builder.get_object("button_refresh").emit("clicked")

        def close_connection_manager():
            if not self.connectionmanager.running:
                return
            self.connectionmanager.builder.get_object("button_close").emit("clicked")

        for host_config in self.connectionmanager.config["hosts"]:
            hostid, host, port, user, passwd = host_config
            if hostid == self.config["autoconnect_host_id"]:
                try_connect = True
                # Check to see if we need to start the localhost daemon
                if self.config["autostart_localhost"] and host in ("localhost", "127.0.0.1"):
                    log.debug("Autostarting localhost:%s", host)
                    try_connect = client.start_daemon(
                        port, get_config_dir()
                    )
                    log.debug("Localhost started: %s", try_connect)
                    if not try_connect:
                        ErrorDialog(
                            _("Error Starting Daemon"),
                            _("There was an error starting the daemon "
                              "process.  Try running it from a console "
                              "to see if there is an error.")
                        ).run()

                    # Daemon Started, let's update it's info
                    reactor.callLater(0.5, update_connection_manager)

                def on_connect(connector):
                    component.start()
                    reactor.callLater(0.2, update_connection_manager)
                    reactor.callLater(0.5, close_connection_manager)

                def on_connect_fail(reason, try_counter,
                                    host, port, user, passwd):
                    if not try_counter:
                        return

                    if reason.check(AuthenticationRequired, BadLoginError):
                        log.debug("PasswordRequired exception")
                        dialog = AuthenticationDialog(reason.value.message, reason.value.username)

                        def dialog_finished(response_id, host, port):
                            if response_id == gtk.RESPONSE_OK:
                                reactor.callLater(
                                    0.5, do_connect, try_counter - 1,
                                    host, port, dialog.get_username(),
                                    dialog.get_password())
                        dialog.run().addCallback(dialog_finished, host, port)
                        return

                    log.info("Connection to host failed..")
                    log.info("Retrying connection.. Retries left: "
                             "%s", try_counter)
                    reactor.callLater(0.5, update_connection_manager)
                    reactor.callLater(0.5, do_connect, try_counter - 1,
                                      host, port, user, passwd)

                def do_connect(try_counter, host, port, user, passwd):
                    log.debug("Trying to connect to %s@%s:%s",
                              user, host, port)
                    d = client.connect(host, port, user, passwd)
                    d.addCallback(on_connect)
                    d.addErrback(on_connect_fail, try_counter,
                                 host, port, user, passwd)

                if try_connect:
                    reactor.callLater(
                        0.5, do_connect, 6, host, port, user, passwd
                    )
                break

    if self.config["show_connection_manager_on_start"]:
        try:
            reactor.simulate()
        except AttributeError:
            # twisted < 12
            reactor.simulate()
        self.connectionmanager.show()

def cli(jail, name):
    """Get a list of jails and print the property."""
    jails = ioc_list.IOCList("uuid").list_datasets()
    pool = ioc_json.IOCJson().json_get_value("pool")
    date = datetime.datetime.utcnow().strftime("%F_%T")

    _jail = {uuid: path for (uuid, path) in jails.items() if
             uuid.startswith(jail)}

    if len(_jail) == 1:
        uuid, path = next(iter(_jail.items()))
    elif len(_jail) > 1:
        ioc_common.logit({
            "level"  : "ERROR",
            "message": f"Multiple jails found for {jail}:"
        })
        for u, p in sorted(_jail.items()):
            ioc_common.logit({
                "level"  : "ERROR",
                "message": f"  {u} ({p})"
            })
        exit(1)
    else:
        ioc_common.logit({
            "level"  : "EXCEPTION",
            "message": f"{jail} not found!"
        }, exit_on_error=True)

    # If they don't supply a snapshot name, we will use the date.
    if not name:
        name = date

    # Looks like foo/iocage/jails/df0ef69a-57b6-4480-b1f8-88f7b6febbdf@BAR
    conf = ioc_json.IOCJson(path).json_load()

    if conf["template"] == "yes":
        target = f"{pool}/iocage/templates/{uuid}@{name}"
    else:
        target = f"{pool}/iocage/jails/{uuid}@{name}"

    try:
        su.check_call(["zfs", "snapshot", "-r", target], stderr=su.PIPE)
        ioc_common.logit({
            "level"  : "INFO",
            "message": f"Snapshot: {target} created."
        })
    except su.CalledProcessError:
        ioc_common.logit({
            "level"  : "EXCEPTION",
            "message": "Snapshot already exists!"
        }, exit_on_error=True)

