def _log_args(self, variables):
    # TODO: Trace log &{kwargs} too.
    args = ['${%s}' % arg for arg in self.arguments.positional]
    if self.arguments.varargs:
        args.append('@{%s}' % self.arguments.varargs)
    args = ['%s=%s' % (name, utils.safe_repr(variables[name]))
            for name in args]
    if 'kwargs' in variables:
        args.append('kwargs=%s' % utils.safe_repr(variables['kwargs']))
    return 'Arguments: [ %s ]' % ' | '.join(args)

def execute(self, args):
    # type: (List[str]) -> Dict[CheckPluginName, Dict[str, Any]]
    manuals = man_pages.all_man_pages()

    check_infos = {}  # type: Dict[CheckPluginName, Dict[str, Any]]
    for check_plugin_name, check in config.check_info.items():
        try:
            manfile = manuals.get(check_plugin_name)
            if manfile:
                title = man_pages.read_title(manfile)
            else:
                title = check_plugin_name

            check_infos[check_plugin_name] = {"title": six.ensure_text(title)}

            if check["group"]:
                check_infos[check_plugin_name]["group"] = check["group"]

            check_infos[check_plugin_name]["service_description"] = check.get(
                "service_description", "%s")
            check_infos[check_plugin_name]["snmp"] = cmk.base.check_utils.is_snmp_check(
                check_plugin_name)
        except Exception as e:
            if cmk.utils.debug.enabled():
                raise
            raise MKAutomationError("Failed to parse man page '%s': %s" %
                                    (check_plugin_name, e))
    return check_infos

def __repr__(self):
    try:
        result_summary = 'SolveSelect {0} results, {1}ms\n-------------\nFirst row\n-------------\n'.format(len(self._build_query()), '1')
        return result_summary + '<Select {0}>'.format(repr(self._build_query()))
    except RuntimeError:
        return repr(self._filters)

def __call__(self, *args, **kwargs):
    height = kwargs.get('height', 512)
    width = kwargs.get('width', 512)
    image = args[0]
    if image.shape[0] != height or image.shape[1] != width:
        image = resize_image(image, height, width)
    return StableDiffusionImg2ImgPipelineMixin.__call__(self, image, *args[1:], **kwargs)


