def select(cls, clause=None, having=None, connection=None, orderBy=None,
           distinct=None):
    attributes, columns = zip(*cls.columns.items())

    if connection is None:
        from stoqlib.database.runtime import get_connection
        connection = get_connection()
    store = connection.store
    clauses = []
    if clause:
        clauses.append(clause)

    if cls.clause:
        clauses.append(cls.clause)

    if clauses:
        clauses = [AND(*clauses)]

    tables = cls._get_tables_for_query(cls.tables[:], clause)

    def _load_view_objects(result, values):
        instance = cls()
        instance._connection = connection
        for attribute, value in zip(attributes, values):
            if hasattr(cls.columns[attribute], 'variable_factory'):
                var = cls.columns[attribute].variable_factory.func()
                if value is not None:
                    value = var.parse_set(value, False)
            setattr(instance, attribute, value)
        return instance

    results = store.using(*tables).find(columns, *clauses)
    if cls.group_by:
        results = results.group_by(*cls.group_by)
    if orderBy:
        results = results.order_by(orderBy)
    if distinct:
        results.config(distinct=True)

    results._load_objects = _load_view_objects
    return results

def YouCompleteMe_UpdateDiagnosticInterface_PrioritizeErrorsOverWarnings_test(
  ycm, vim_command, post_vim_message, *args ):

  contents = """int main() {
  int x, y;
  x == y;
}"""

  # List of diagnostics returned by ycmd for the above code.
  diagnostics = [ {
    'kind': 'ERROR',
    'text': "expected ';' after expression",
    'location': {
      'filepath': 'buffer',
      'line_num': 3,
      'column_num': 9
    },
    # Looks strange but this is really what ycmd is returning.
    'location_extent': {
      'start': {
        'filepath': '',
        'line_num': 0,
        'column_num': 0,
      },
      'end': {
        'filepath': '',
        'line_num': 0,
        'column_num': 0,
      }
    },
    'ranges': [],
    'fixit_available': True
  }, {
    'kind': 'WARNING',
    'text': 'equality comparison result unused',
    'location': {
      'filepath': 'buffer',
      'line_num': 3,
      'column_num': 7,
    },
    'location_extent': {
      'start': {
        'filepath': 'buffer',
        'line_num': 3,
        'column_num': 5,
      },
      'end': {
        'filepath': 'buffer',
        'line_num': 3,
        'column_num': 7,
      }
    },
    'ranges': [ {
      'start': {
        'filepath': 'buffer',
        'line_num': 3,
        'column_num': 3,
      },
      'end': {
        'filepath': 'buffer',
        'line_num': 3,
        'column_num': 9,
      }
    } ],
    'fixit_available': True
  } ]

  current_buffer = VimBuffer( 'buffer',
                              filetype = 'c',
                              contents = contents.splitlines(),
                              number = 5,
                              window = 2 )

  test_utils.VIM_MATCHES = []

  with MockVimBuffers( [ current_buffer ], current_buffer, ( 3, 1 ) ):
    with patch( 'ycm.client.event_notification.EventNotification.Response',
                return_value = diagnostics ):
      ycm.OnFileReadyToParse()
      ycm.HandleFileParseRequest( block = True )

    # Error match is added after warning matches.
    assert_that(
      test_utils.VIM_MATCHES,
      contains(
        VimMatch( 'YcmWarningSection', '\%3l\%5c\_.\{-}\%3l\%7c' ),
        VimMatch( 'YcmWarningSection', '\%3l\%3c\_.\{-}\%3l\%9c' ),
        # FIXME: match should be inserted at the end of line 3 (missing ";").
        VimMatch( 'YcmErrorSection', '\%0l\%0c' )
      )
    )

    # Only the error sign is placed.
    vim_command.assert_has_exact_calls( [
      call( 'sign define ycm_dummy_sign' ),
      call( 'sign place 3 name=ycm_dummy_sign line=3 buffer=5' ),
      call( 'sign place 1 name=YcmError line=3 buffer=5' ),
      call( 'sign undefine ycm_dummy_sign' ),
      call( 'sign unplace 3 buffer=5' )
    ] )

    # When moving the cursor on the diagnostics, the error is displayed to the
    # user, not the warning.
    ycm.OnCursorMoved()
    post_vim_message.assert_has_exact_calls( [
      call( "expected ';' after expression (FixIt)",
            truncate = True, warning = False )
    ] )
